/* New Detroit character terminal. No runtime dependencies. */
'use strict';
const D=window.ND_DATA,E=window.ND_ENGINE,C=window.ND_CLOUD;
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let card=E.clone(D.initial),tab='overview',cloudRecord=null,canEdit=true,dirty=false,version=0,saving=false,saveTimer,conflict=false,search='',category='all';
let status='Локальная копия · только этот браузер';
try{const saved=localStorage.getItem('nd-local-v1');if(saved)card=E.validate(JSON.parse(saved),D);}catch{status='Не удалось прочитать локальную копию. Доступен исходный лист';}
const tabs=[['overview','01','Персонаж'],['equipment','02','Снаряжение'],['chrome','03','Хром и сеть'],['inventory','04','Инвентарь'],['notes','05','Журнал'],['reference','06','Справочник']];
const labels={weapons:'Оружие',armor:'Броня',implants:'Импланты',programs:'Черви и демоны',perks:'Перки',consumables:'Расходники'};
function notify(t){$('#toast').textContent=t;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function setStatus(t){status=t;const el=$('#save-status');if(el)el.textContent=t;}
const field=(label,path,value,type='text')=>`<label class="field"><span>${label}</span><input data-path="${path}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="1"':''}></label>`;
const area=(label,path,value)=>`<label class="field"><span>${label}</span><textarea data-path="${path}" rows="4">${esc(value)}</textarea></label>`;
function selector(path,selected,options,label){return `<select aria-label="${esc(label)}" data-path="${path}">${options.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x===''?'Не выбрано':x)}</option>`).join('')}</select>`;}
function section(title,body,meta=''){return `<section class="panel"><header class="panel-head"><h2>${title}</h2><span>${meta}</span></header>${body}</section>`;}
function pips(kind,n,current){return `<div class="pips">${Array.from({length:n},(_,i)=>`<button class="pip ${i<current?'filled':''}" data-pip="${kind}" data-value="${i+1}" aria-label="${kind==='hp'?'Здоровье':'Броня'}: ${i+1}" aria-pressed="${i<current}"></button>`).join('')}</div>`;}
function metrics(){const d=E.derive(card,D.catalog);return `<div class="metrics"><section class="metric health"><div class="eyebrow">ЖИЗНЕННЫЕ ПОКАЗАТЕЛИ</div><div class="metric-line"><h2>Здоровье</h2><strong>${card.hp}<small> / ${d.maxHP}</small></strong></div>${pips('hp',d.maxHP,card.hp)}<div class="micro">Максимум: 3 + Тело</div></section><section class="metric"><div class="eyebrow">АКТИВНАЯ ЗАЩИТА</div><div class="metric-line"><h2>Броня</h2><strong>${d.currentArmor}<small> / ${d.armor}</small></strong></div>${d.armor?pips('armor',d.armor,d.currentArmor):'<div class="empty-pips">Защита не экипирована</div>'}<div class="micro">${esc(card.armor||'Без брони')}</div></section><section class="metric chrome"><div class="eyebrow">НЕЙРОННАЯ НАГРУЗКА</div><div class="metric-line"><h2>Хром</h2><strong>${d.used}<small> / ${d.capacity}</small></strong></div><div class="bar"><i style="width:${Math.min(100,d.used/d.capacity*100)}%"></i></div><div class="micro ${d.freeChrome<0?'warning':''}">${d.freeChrome>=0?`Свободно слотов: ${d.freeChrome}`:`Киберпсихоз: ${d.psychosis} · превышение лимита`}</div></section></div>`;}
function loadout(kind,count){const arr=kind==='armor'?[card.armor]:card[kind];return arr.slice(0,count??arr.length).map((item,i)=>{
 const name=typeof item==='object'?item.name:item;const entry=D.catalog[kind].find(x=>x.name===name);
 const path=kind==='armor'?'armor':`${kind}.${i}${typeof item==='object'?'.name':''}`;
 return `<article class="loadout"><div class="slot-index">${String(i+1).padStart(2,'0')}</div><div class="loadout-body">${selector(path,name,['',...D.catalog[kind].map(x=>x.name)],labels[kind]+' · слот '+(i+1))}${entry?`<div class="item-tags">${[['damage','УРОН'],['range','ГЕКСЫ'],['slot','ХВАТ'],['armor','БРОНЯ'],['slots','ХРОМ'],['type',''],['placement',''],['cost','ОО']].filter(([k])=>entry[k]!=null).map(([k,l])=>`<span>${esc(entry[k])} ${l}</span>`).join('')}</div><details><summary>Эффект и описание</summary><p>${esc(entry.description)}</p>${entry.target?`<p>Цель: ${esc(entry.target)}<br>Сложность: ${esc(entry.difficulty)}</p>`:''}</details>`:'<div class="micro slot-empty">Свободный слот</div>'}${kind==='implants'?field('Качество',`implants.${i}.quality`,item.quality):''}${kind==='consumables'?field('Количество',`consumables.${i}.quantity`,item.quantity,'number'):''}</div></article>`;
 }).join('');}
function overview(){const d=E.derive(card,D.catalog);return `<div class="overview-grid"><div class="main-col">${section('Характеристики',`<div class="attributes">${D.attributes.map((a,i)=>`<div class="attribute"><div class="attribute-top"><span>0${i+1}</span>${selector('attributes.'+i,card.attributes[i],[0,1,2],a.name)}</div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p></div>`).join('')}</div><p class="hint ${d.validAttributes?'':'warning'}">${d.validAttributes?'Распределение 2 / 1 / 1 / 0':'Проверь распределение: по листу требуется 2 / 1 / 1 / 0'}</p>`,'БАЗОВЫЕ ПАРАМЕТРЫ')}${section('Навыки',`<div class="skills">${D.skills.map((s,i)=>`<div class="skill"><details><summary>${esc(s.name)}</summary><p>${esc(s.description)}</p></details>${selector('skills.'+i,card.skills[i],[0,1,2,3],s.name)}</div>`).join('')}</div><div class="budget ${d.skillPoints<0?'warning':''}">Свободные очки <strong>${d.skillPoints}</strong><small>4 + Нейропластичность − ранги навыков</small></div>`,'РАНГ 0—3')}</div><div class="side-col">${section('Активное оружие',loadout('weapons'),'2 СЛОТА')}${section('Перки',loadout('perks'),'5 СЛОТОВ')}</div></div>`;}
function inventory(){return section('Инвентарь',`<div class="money">${field('Баланс · ED','money',card.money,'number')}</div><div class="table-wrap"><table><thead><tr><th>Наименование</th><th>Описание</th><th></th></tr></thead><tbody>${card.inventory.map((r,i)=>`<tr><td><input aria-label="Наименование ${i+1}" data-path="inventory.${i}.name" value="${esc(r.name)}"></td><td><textarea aria-label="Описание ${i+1}" data-path="inventory.${i}.description">${esc(r.description)}</textarea></td><td><button data-remove="inventory" data-index="${i}" aria-label="Удалить предмет ${i+1}">×</button></td></tr>`).join('')}</tbody></table></div>${!card.inventory.length?'<p class="empty">В карманах пока пусто. Добавь предмет, который стоит взять с собой.</p>':''}<button class="outline add" data-add="inventory">+ Добавить предмет</button>`);}
function notes(){return section('Журнал и заметки',`${card.notes.map((r,i)=>`<article class="note"><div class="two-cols">${field('Локация',`notes.${i}.location`,r.location)}${field('Имя персонажа / NPC',`notes.${i}.npc`,r.npc)}</div>${area('Комментарий игрока',`notes.${i}.text`,r.text)}<button data-remove="notes" data-index="${i}">Удалить запись</button></article>`).join('')}${!card.notes.length?'<p class="empty">У каждой улицы есть история.<br>Здесь будут твои зацепки, контакты и последствия решений.</p>':''}<button class="outline add" data-add="notes">+ Добавить запись</button>`);}
function reference(){return `<section class="panel"><header class="panel-head"><h2>Справочник</h2><span>ИЗ ЛИСТА ПЕРСОНАЖА</span></header><div class="reference-tools"><input id="search" type="search" placeholder="Найти предмет или эффект…" aria-label="Поиск по справочнику" value="${esc(search)}"><select id="category" aria-label="Категория"><option value="all">Все категории</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${category===k?'selected':''}>${v}</option>`).join('')}</select></div><div id="results">${referenceResults()}</div><details class="backlash"><summary>Механика отката</summary><p>${esc(D.backlash)}</p></details></section>`;}
function referenceResults(){const items=Object.entries(D.catalog).flatMap(([k,items])=>items.map(i=>({...i,category:k}))).filter(x=>(category==='all'||category===x.category)&&JSON.stringify(x).toLowerCase().includes(search.toLowerCase()));return `<p class="hint">Найдено: ${items.length}</p><div class="reference-grid">${items.map(x=>`<article class="reference-card"><span class="eyebrow">${labels[x.category]}</span><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><div class="item-tags">${Object.entries(x).filter(([k,v])=>!['category','name','description'].includes(k)&&v!=null).map(([k,v])=>`<span>${esc(({damage:'Урон',range:'Дальность',slot:'Хват',armor:'Броня',slots:'Слоты',type:'Тип',placement:'Размещение',cost:'ОО',target:'Цель',difficulty:'Сложность'})[k])}: ${esc(v)}</span>`).join('')}</div></article>`).join('')}</div>`;}
function render(){const displayName=card.nickname||card.name||'Без псевдонима';$('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="${esc(location.hash||'#')}" aria-label="Нью Детроит"><span class="brand-mark">N<span>D</span></span><span>НЬЮ<br>ДЕТРОИТ<small>CHARACTER SYSTEM / 1.0</small></span></a><div class="nav-caption">ЛИЧНОЕ ДЕЛО</div><nav>${tabs.map(([id,num,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}><span>${num}</span>${name}<b>↗</b></button>`).join('')}</nav><div class="sidebar-bottom"><div class="city-grid"></div><span class="eyebrow">NEW DETROIT</span><p>История выше механик.<br>Решения имеют последствия.</p><button id="cloud-button" class="outline">${C.user()?'Мои карточки':'Подключение и доступ'} ↗</button><span class="version">ND / CHARACTER TERMINAL · V1.0</span></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">НЬЮ ДЕТРОИТ <span>/</span> ${tabs.find(x=>x[0]===tab)[2]}</div><div class="top-actions"><button id="export">Экспорт ↓</button><button id="import">Импорт ↑</button><button id="share" class="yellow">Поделиться ↗</button></div></header><main><div class="heading"><div><div class="eyebrow">ДОСЬЕ ПЕРСОНАЖА / ${cloudRecord?'СЕТЬ':'ЛОКАЛЬНО'}</div><h1>${esc(displayName)}</h1></div><div class="save-indicator"><i></i><span id="save-status" role="status">${esc(status)}</span></div></div>${tab==='overview'?`<section class="profile"><div class="portrait"><img src="portrait.jpg" alt="Портрет из исходной карточки"><span>PERSONNEL FILE / 001</span></div><div class="profile-info"><div class="profile-title"><span class="eyebrow">ИДЕНТИФИКАЦИЯ</span><span class="tag">${canEdit?'РЕДАКТИРОВАНИЕ':'ТОЛЬКО ПРОСМОТР'}</span></div><div class="profile-fields">${field('Имя персонажа','name',card.name)}${field('Никнейм','nickname',card.nickname)}${field('Возраст','age',card.age)}</div>${area('Краткая история','bio',card.bio)}</div></section>`:''}${tab!=='reference'?metrics():''}<div id="content">${tab==='overview'?overview():tab==='equipment'?`<div class="two-cols">${section('Активное оружие',loadout('weapons'))}${section('Одежда и броня',loadout('armor'))}</div>${section('Расходники',loadout('consumables'))}`:tab==='chrome'?`<div class="two-cols">${section('Активные импланты',loadout('implants'),'9 СЛОТОВ')}${section('Черви и демоны',loadout('programs'),'5 СЛОТОВ')}</div><p class="hint">Как в таблице: слоты хрома считаются автоматически. Условные эффекты имплантов применяются вручную.</p>`:tab==='inventory'?inventory():tab==='notes'?notes():reference()}</div><footer>NEW DETROIT / СИСТЕМА ПЕРСОНАЖА <span>ТВОЯ ИСТОРИЯ. ТВОЙ СЛЕД.</span></footer></main></div>`;
 if(!canEdit)document.querySelectorAll('[data-path],[data-pip],[data-add],[data-remove]').forEach(x=>x.disabled=true);
 bind();}
function update(path,value){if(!canEdit)return;let obj=card;const parts=path.split('.');for(const key of parts.slice(0,-1))obj=obj[key];obj[parts.at(-1)]=value;
 const d=E.derive(card,D.catalog);card.hp=Math.min(card.hp,d.maxHP);card.armorSpent=Math.min(card.armorSpent,d.armor);
 changed();}
function changed(){dirty=true;version++;try{localStorage.setItem(cloudRecord?'nd-draft-'+C.user()?.id+'-'+cloudRecord.id:'nd-local-v1',JSON.stringify(card));}catch{notify('Браузер не разрешил сохранение. Скачай экспорт.');}
 if(cloudRecord){setStatus(conflict?'Конфликт · сохрани экспорт перед загрузкой':'Изменения ожидают отправки…');clearTimeout(saveTimer);saveTimer=setTimeout(save,700);}else{dirty=false;setStatus('Сохранено в этом браузере · без синхронизации');}}
async function save(){if(!cloudRecord||!dirty||saving||conflict)return;saving=true;const snapshot=E.clone(card),v=version;setStatus('Сохраняем в облаке…');try{E.validate(snapshot,D);cloudRecord=await C.save(cloudRecord.id,snapshot,cloudRecord.revision);if(v===version){dirty=false;localStorage.removeItem('nd-draft-'+C.user()?.id+'-'+cloudRecord.id);}setStatus(dirty?'Ожидают отправки новые изменения…':'Синхронизировано · '+new Date().toLocaleTimeString('ru-RU'));}catch(e){conflict=true;setStatus('Не синхронизировано · локальная копия сохранена');notify(e.message);}finally{saving=false;if(dirty&&!conflict)setTimeout(save,100);}}
function bind(){document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();window.scrollTo(0,0);});
 document.querySelectorAll('[data-path]').forEach(el=>{const handle=()=>{let value=el.value;const path=el.dataset.path;if(/^(attributes|skills)\./.test(path)||path==='money'||path.endsWith('.quantity')){value=value===''&&path.endsWith('.quantity')?'':Number(value);if(value!==''&&(!Number.isFinite(value)||value<0||!Number.isInteger(value))){notify('Нужно целое неотрицательное число');return;}}update(path,value);if(el.tagName==='SELECT')render();else if(path==='name'||path==='nickname')$('h1').textContent=card.nickname||card.name||'Без псевдонима';};if(el.tagName==='SELECT')el.onchange=handle;else el.oninput=handle;});
 document.querySelectorAll('[data-pip]').forEach(b=>b.onclick=()=>{if(!canEdit)return;const n=+b.dataset.value,d=E.derive(card,D.catalog);if(b.dataset.pip==='hp')card.hp=card.hp===n?n-1:n;else card.armorSpent=d.armor-(d.currentArmor===n?n-1:n);changed();render();});
 document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(!canEdit)return;card[b.dataset.add].push(b.dataset.add==='notes'?{location:'',npc:'',text:''}:{name:'',description:''});changed();render();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!canEdit)return;const k=b.dataset.remove,i=+b.dataset.index,removed=card[k][i];modal('Удалить запись?',`<p>${esc(k==='notes'?(removed.npc||removed.location||'Запись журнала'):(removed.name||'Предмет'))}</p><button class="yellow" id="confirm-delete">Удалить</button>`);$('#confirm-delete').onclick=()=>{card[k].splice(i,1);changed();closeModal();render();};});
 $('#export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'new-detroit-v1',character:card},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='new-detroit-character.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 $('#import').onclick=()=>{if(saving||dirty){notify('Сначала сохрани облачные изменения или разреши конфликт через «Мои карточки».');return;}const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{if(input.files[0].size>1000000)throw Error('Файл слишком большой');const parsed=JSON.parse(await input.files[0].text());const imported=E.validate(parsed.character||parsed,D);modal('Открыть импорт как локальную копию?', '<p>Текущая облачная карточка не будет заменена. Сначала экспортируй текущую локальную копию, если она нужна.</p><button class="yellow" id="confirm-import">Открыть копию</button>');$('#confirm-import').onclick=()=>{clearTimeout(saveTimer);cloudRecord=null;conflict=false;canEdit=true;card=imported;history.replaceState(null,'',location.pathname+location.search);changed();closeModal();render();};}catch(e){notify(e.message);}};input.click();};
 $('#cloud-button').onclick=cloudMenu;$('#share').onclick=shareMenu;
 if($('#search'))$('#search').oninput=e=>{search=e.target.value;$('#results').innerHTML=referenceResults();};
 if($('#category'))$('#category').onchange=e=>{category=e.target.value;$('#results').innerHTML=referenceResults();};
}
function modal(title,html){$('#dialog').innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button id="close-modal" aria-label="Закрыть">×</button></div>${html}<p id="dialog-error" role="alert"></p>`;$('#close-modal').onclick=closeModal;if(!$('#dialog').open)$('#dialog').showModal();}
function closeModal(){$('#dialog').close();}
function error(e){if($('#dialog-error'))$('#dialog-error').textContent=e.message;else notify(e.message);}
function cloudMenu(){if(!C.configured()){modal('Подключение к общей игре',`<p>Сейчас карточка сохраняется только в этом браузере. Чтобы игрок и мастер видели одну версию, подключи Supabase по инструкции из проекта.</p><ol><li>Создай бесплатный проект Supabase.</li><li>Выполни файл <code>supabase.sql</code>.</li><li>Внеси Project URL и публичный ключ в <code>config.js</code>.</li><li>Опубликуй папку сайта через GitHub Pages.</li></ol><p>Затем здесь появятся вход, список карточек и управление доступом.</p>`);return;}
 if(!C.user()){modal('Вход в Нью Детроит',`<form id="login-form"><label class="field"><span>Email</span><input name="email" type="email" autocomplete="email" required></label><label class="field"><span>Пароль</span><input name="password" type="password" autocomplete="current-password" minlength="8" required></label><button class="yellow" type="submit">Войти</button><button type="button" id="register">Создать аккаунт</button></form><p class="hint">Владелец карточки выдаёт доступ на твой email. После регистрации подтверди адрес по письму.</p>`);const form=$('#login-form');form.onsubmit=async e=>{e.preventDefault();try{await C.login(form.email.value,form.password.value);const id=cardId();if(id){closeModal();await openCard(id);}else await cloudMenu();render();}catch(e){error(e);}};$('#register').onclick=async()=>{if(!form.reportValidity())return;try{await C.signup(form.email.value,form.password.value);notify('Регистрация отправлена. Подтверди email и войди.');}catch(e){error(e);}};return;}
 modal('Мои карточки',`<p>${esc(C.user().email)}</p><div id="card-list">Загрузка…</div>${conflict?'<p class="warning">Сохранение остановлено. Сначала скачай экспорт текущих правок.</p><button id="reload-cloud">Загрузить облачную версию</button><button id="retry-save">Повторить сохранение</button>':''}<button id="create-card" class="yellow">Создать облачную копию текущей</button><button id="logout">Выйти</button>`);
 if($('#retry-save'))$('#retry-save').onclick=async()=>{conflict=false;await save();cloudMenu();};
 if($('#reload-cloud'))$('#reload-cloud').onclick=()=>{modal('Загрузить актуальную версию?', '<p>Текущие неотправленные правки будут заменены. Скачай экспорт, если они нужны.</p><button id="confirm-reload" class="yellow">Загрузить из облака</button>');$('#confirm-reload').onclick=async()=>{try{localStorage.removeItem('nd-draft-'+C.user().id+'-'+cloudRecord.id);await openCard(cloudRecord.id);closeModal();}catch(e){error(e);}};};
 $('#create-card').onclick=async()=>{try{await save();if(saving||dirty)throw Error('Сначала сохрани или экспортируй текущие изменения');const r=await C.create(E.validate(card,D));closeModal();await openCard(r.id);notify('Облачная карточка создана');}catch(e){error(e);}};
 $('#logout').onclick=async()=>{try{await save();if(dirty||saving)throw Error('Есть неотправленные изменения. Сначала скачай экспорт и восстанови соединение.');await C.logout();cloudRecord=null;canEdit=true;card=E.clone(D.initial);status='Локальная копия · только этот браузер';history.replaceState(null,'',location.pathname);closeModal();render();}catch(e){error(e);}};
 C.list().then(rows=>{if(!$('#card-list'))return;$('#card-list').innerHTML=rows.length?rows.map(r=>`<button class="card-link" data-open="${esc(r.id)}"><strong>${esc(r.data.nickname||r.data.name||'Без псевдонима')}</strong><span>${r.owner_id===C.user().id?'Владелец':'Общий доступ'} · ${new Date(r.updated_at).toLocaleString('ru-RU')}</span></button>`).join(''):'<p>Карточек пока нет.</p>';document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{try{if(dirty||saving)throw Error('Сначала сохрани изменения или экспортируй копию');closeModal();await openCard(b.dataset.open);}catch(e){error(e);}});}).catch(error);
}
function cardId(){return new URLSearchParams(location.hash.slice(1)).get('card');}
async function openCard(id){if(!/^[0-9a-f-]{36}$/i.test(id))throw Error('Некорректная ссылка на карточку');const r=await C.load(id);const candidate=E.validate(r.data,D);const grants=await C.grants(id);clearTimeout(saveTimer);card=candidate;cloudRecord=r;canEdit=r.owner_id===C.user().id||grants.some(g=>g.email===C.user().email.toLowerCase()&&g.role==='editor');dirty=false;conflict=false;history.replaceState(null,'','#card='+id);status='Синхронизировано · '+(canEdit?'можно редактировать':'только просмотр');render();const draft=localStorage.getItem('nd-draft-'+C.user().id+'-'+id);if(draft&&canEdit){modal('Есть неотправленная локальная копия', '<p>Она могла остаться после потери соединения. Открыта свежая версия из облака. Восстановление заменит её данными локальной копии при следующем сохранении.</p><button id="restore-draft" class="yellow">Восстановить локальную копию</button><button id="discard-draft">Оставить облачную версию</button>');$('#restore-draft').onclick=()=>{try{card=E.validate(JSON.parse(draft),D);changed();closeModal();render();}catch(e){error(e);}};$('#discard-draft').onclick=()=>{localStorage.removeItem('nd-draft-'+C.user().id+'-'+id);closeModal();};}}
async function shareMenu(){if(!cloudRecord){cloudMenu();return;}const owner=cloudRecord.owner_id===C.user()?.id;modal('Доступ к карточке',`<p>Ссылка открывает эту карточку после входа. Доступ выдаётся отдельно по email.</p><label class="field"><span>Ссылка на карточку</span><input id="share-url" readonly value="${esc(location.href)}"></label><button id="copy-link" class="yellow">Копировать ссылку</button>${owner?'<form id="grant-form"><label class="field"><span>Email игрока или мастера</span><input name="email" type="email" required></label><label class="field"><span>Права</span><select name="role"><option value="editor">Редактирование</option><option value="viewer">Только просмотр</option></select></label><button type="submit">Выдать доступ</button></form><div id="access-list"></div>':'<p>Изменять список участников может владелец карточки.</p>'}`);
 $('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);notify('Ссылка скопирована');}catch{$('#share-url').select();notify('Скопируй выделенную ссылку');}};
 if(owner){const list=async()=>{const grants=await C.grants(cloudRecord.id);$('#access-list').innerHTML=grants.map(g=>`<div class="access-row"><span>${esc(g.email)} · ${g.role==='editor'?'Редактор':'Просмотр'}</span><button data-revoke="${esc(g.email)}">Отозвать</button></div>`).join('');document.querySelectorAll('[data-revoke]').forEach(b=>b.onclick=async()=>{try{await C.revoke(cloudRecord.id,b.dataset.revoke);await list();}catch(e){error(e);}});};$('#grant-form').onsubmit=async e=>{e.preventDefault();try{await C.grant(cloudRecord.id,e.target.email.value,e.target.role.value);await list();notify('Доступ выдан. Отправь участнику ссылку.');}catch(e){error(e);}};try{await list();}catch(e){error(e);}}
}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>{if(dirty&&!conflict)save();});
setInterval(async()=>{if(!cloudRecord||dirty||saving||document.hidden||$('#dialog').open||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;try{const fresh=await C.load(cloudRecord.id);if(fresh.revision!==cloudRecord.revision){card=E.validate(fresh.data,D);cloudRecord=fresh;setStatus('Обновлено из облака · '+new Date().toLocaleTimeString('ru-RU'));render();}}catch(e){setStatus('Нет обновлений: проверь соединение или доступ');}},10000);
render();if(cardId()){if(C.user())openCard(cardId()).catch(e=>{notify(e.message);cloudMenu();});else cloudMenu();}
